import{_ as e}from"./chunks/01-settings-home.ERQr-o42.js";import{_ as a}from"./chunks/02-model-link-create.GYs-TGFF.js";import{_ as r}from"./chunks/03-model-link-test-ok.C1zJ0t_x.js";import{_ as i,a as o,b as l}from"./chunks/05-chara-import-preview.r1fRrlru.js";import{_ as n}from"./chunks/06-chat-first-message.BgaA9QkL.js";import{_ as s,o as d,c,a2 as p}from"./chunks/framework.z3u3TMv0.js";const P=JSON.parse('{"title":"Getting started","description":"MiniTavern Ultra first-run guide — set up a model link, import a character card, and send your first AI roleplay message.","frontmatter":{"title":"Getting started","description":"MiniTavern Ultra first-run guide — set up a model link, import a character card, and send your first AI roleplay message.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"Getting started · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern Ultra first-run guide — set up a model link, import a character card, and send your first AI roleplay message."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en/manual/getting-started"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en/manual/getting-started"}]]},"headers":[],"relativePath":"en/manual/getting-started.md","filePath":"en/manual/getting-started.md","lastUpdated":1787224147000}'),m={name:"en/manual/getting-started.md"};function g(h,t,u,f,_,b){return d(),c("div",null,[...t[0]||(t[0]=[p('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>Goal: finish “model configured → have a character card → send the first message.”</p><h2 id="steps-overview" tabindex="-1">Steps overview <a class="header-anchor" href="#steps-overview" aria-label="Permalink to &quot;Steps overview&quot;">​</a></h2><ol><li>Open the App and go to bottom <strong>Settings</strong>.</li><li>Configure a <a href="./model-link">Model link</a>, test successfully, and set it as default.</li><li>Bottom <strong>Characters</strong> → import or create a character.</li><li>Start a chat from the character and send a message.</li></ol><h2 id="_1-configure-ai-model-link" tabindex="-1">1. Configure AI (model link) <a class="header-anchor" href="#_1-configure-ai-model-link" aria-label="Permalink to &quot;1. Configure AI (model link)&quot;">​</a></h2><p>Path: <strong>Settings → Models → Model link → New</strong></p><p><img src="'+e+'" alt="Settings home"></p><ol><li>Enter a name (defaults are fine).</li><li>Choose a <strong>model platform</strong> (OpenAI, DeepSeek, Custom (OpenAI), etc.).</li><li>Paste the <strong>API Key</strong> (local services can often leave it blank or use a placeholder).</li><li>Confirm <strong>Base URL</strong> (required for custom protocols, e.g. <code>https://api.xxx.com/v1</code>).</li><li>Select or type the <strong>model</strong> ID.</li><li>Tap <strong>Test</strong>; save after success, then set it as <strong>Default</strong> in the list.</li></ol><p><img src="'+a+'" alt="Create model link"></p><p><img src="'+r+'" alt="Test succeeded"></p><p>On failure, tap “View details” and check <a href="./errors">Error codes</a>.</p><h2 id="_2-import-your-first-character-card" tabindex="-1">2. Import your first character card <a class="header-anchor" href="#_2-import-your-first-character-card" aria-label="Permalink to &quot;2. Import your first character card&quot;">​</a></h2><p>Path: bottom <strong>Characters</strong> → Create / Import</p><p><img src="'+i+'" alt="Character list"></p><p><img src="'+o+'" alt="Import options"></p><table tabindex="0"><thead><tr><th>Method</th><th>Action</th></tr></thead><tbody><tr><td>File</td><td>Pick a PNG (tavern card) or JSON</td></tr><tr><td>Photos</td><td>Pick a PNG card image from the album</td></tr><tr><td>Link</td><td>Paste a character card download URL</td></tr><tr><td>Sample</td><td>Follow the prompt to import a built-in sample (if available)</td></tr></tbody></table><p>A single card opens <strong>preview</strong> first: confirm “Create new” or “Update same name”, and optionally copy the card’s lorebook / regex into the global libraries. Only after confirm does it enter the library.</p><p><img src="'+l+'" alt="Import preview"></p><h2 id="_3-start-chatting" tabindex="-1">3. Start chatting <a class="header-anchor" href="#_3-start-chatting" aria-label="Permalink to &quot;3. Start chatting&quot;">​</a></h2><ol><li>Open a chat from the character (or enter an existing session from the <strong>Chat</strong> tab).</li><li>If there are multiple greetings, pick one when prompted.</li><li>Type and send; replies can stream.</li><li>If no model is configured, the chat page prompts you to set up AI first.</li></ol><p><img src="'+n+'" alt="Chat page"></p><h2 id="_4-suggested-next-steps" tabindex="-1">4. Suggested next steps <a class="header-anchor" href="#_4-suggested-next-steps" aria-label="Permalink to &quot;4. Suggested next steps&quot;">​</a></h2><ul><li><a href="./chat">Chat</a>: continue, regenerate, per-chat model / lorebook</li><li><a href="./backup">Backup</a>: make a full backup soon</li><li>No paid Key: <a href="/ultra_guides/en/free-cloud/">Free cloud APIs</a></li><li>Local PC models: <a href="/ultra_guides/en/quickstart">30-minute quickstart</a> · <a href="/ultra_guides/en/local/">Run local models</a></li><li>On-device image gen: <a href="/ultra_guides/en/local/image-gen/">Image model deploy</a></li></ul>',23)])])}const x=s(m,[["render",g]]);export{P as __pageData,x as default};
